macro_rules! deps {
    () => {
        AllowedOptions!();
        PersistOptions!();
    };
}

macro_rules! Options {
    () => {
        deps!();
        # [doc = " \"Options\" are flags that can be supplied to the various salsa related"] # [doc = " macros. They are listed like `(ref, no_eq, foo=bar)` etc. The commas"] # [doc = " are required and trailing commas are permitted. The options accepted"] # [doc = " for any particular location are configured via the `AllowedOptions`"] # [doc = " trait."] # [derive (Debug)] pub (crate) struct Options < A : AllowedOptions > { # [doc = " The `returns` option is used to configure the \"return mode\" for the field/function."] # [doc = " This may be one of `copy`, `clone`, `ref`, `as_ref`, `as_deref`."] # [doc = ""] # [doc = " If this is `Some`, the value is the ident representing the selected mode."] pub returns : Option < syn :: Ident > , # [doc = " The `no_eq` option is used to signal that a given field does not implement"] # [doc = " the `Eq` trait and cannot be compared for equality."] # [doc = ""] # [doc = " If this is `Some`, the value is the `no_eq` identifier."] pub no_eq : Option < syn :: Ident > , # [doc = " Signal we should generate a `Debug` impl."] # [doc = ""] # [doc = " If this is `Some`, the value is the `debug` identifier."] pub debug : Option < syn :: Ident > , # [doc = " Signal we should not include the `'db` lifetime."] # [doc = ""] # [doc = " If this is `Some`, the value is the `no_lifetime` identifier."] pub no_lifetime : Option < syn :: Ident > , # [doc = " The `singleton` option is used on input with only one field"] # [doc = " It allows the creation of convenient methods"] pub singleton : Option < syn :: Ident > , # [doc = " The `specify` option is used to signal that a tracked function can"] # [doc = " have its value externally specified (at least some of the time)."] # [doc = ""] # [doc = " If this is `Some`, the value is the `specify` identifier."] pub specify : Option < syn :: Ident > , # [doc = " The `non_update_return_type` option is used to signal that a tracked function's"] # [doc = " return type does not require `Update` to be implemented. This is unsafe and"] # [doc = " generally discouraged as it allows for dangling references."] # [doc = ""] # [doc = " If this is `Some`, the value is the `non_update_return_type` identifier."] pub non_update_return_type : Option < syn :: Ident > , # [doc = " The `persist` options indicates that the ingredient should be persisted with the database."] # [doc = ""] # [doc = " If this is `Some`, the value is optional paths to custom serialization/deserialization"] # [doc = " functions, based on `serde::{Serialize, Deserialize}`."] pub persist : Option < PersistOptions > , # [doc = " The `db = <path>` option is used to indicate the db."] # [doc = ""] # [doc = " If this is `Some`, the value is the `<path>`."] pub db_path : Option < syn :: Path > , # [doc = " The `cycle_fn = <path>` option is used to indicate the cycle recovery function."] # [doc = ""] # [doc = " If this is `Some`, the value is the `<path>`."] pub cycle_fn : Option < syn :: Path > , # [doc = " The `cycle_initial = <path>` option is the initial value for cycle iteration."] # [doc = ""] # [doc = " If this is `Some`, the value is the `<path>`."] pub cycle_initial : Option < syn :: Path > , # [doc = " The `cycle_result = <path>` option is the result for non-fixpoint cycle."] # [doc = ""] # [doc = " If this is `Some`, the value is the `<path>`."] pub cycle_result : Option < syn :: Expr > , # [doc = " The `data = <ident>` option is used to define the name of the data type for an interned"] # [doc = " struct."] # [doc = ""] # [doc = " If this is `Some`, the value is the `<ident>`."] pub data : Option < syn :: Ident > , # [doc = " The `lru = <usize>` option is used to set the lru capacity for a tracked function."] # [doc = ""] # [doc = " If this is `Some`, the value is the `<usize>`."] pub lru : Option < usize > , # [doc = " The `constructor = <ident>` option lets the user specify the name of"] # [doc = " the constructor of a salsa struct."] # [doc = ""] # [doc = " If this is `Some`, the value is the `<ident>`."] pub constructor_name : Option < syn :: Ident > , # [doc = " The `id = <path>` option is used to set a custom ID for interrned structs."] # [doc = ""] # [doc = " The ID must implement `salsa::plumbing::AsId` and `salsa::plumbing::FromId`."] # [doc = " If this is `Some`, the value is the `<ident>`."] pub id : Option < syn :: Path > , # [doc = " The `revisions = <usize>` option is used to set the minimum number of revisions"] # [doc = " to keep a value interned."] # [doc = ""] # [doc = " This is stored as a `syn::Expr` to support `usize::MAX`."] pub revisions : Option < syn :: Expr > , # [doc = " The `heap_size = <path>` option can be used to track heap memory usage of memoized"] # [doc = " values."] # [doc = ""] # [doc = " If this is `Some`, the value is the provided `heap_size` function."] pub heap_size_fn : Option < syn :: Path > , # [doc = " The `self_ty = <Ty>` option is used to set the the self type of the tracked impl for tracked"] # [doc = " functions. This is merely used to refine the query name."] pub self_ty : Option < syn :: Type > , # [doc = " Remember the `A` parameter, which plays no role after parsing."] phantom : PhantomData < A > , }
    };
}

Options!();